package com.readwide.manager.archive;
import static org.junit.Assert.*;
import org.junit.*;import org.junit.rules.TemporaryFolder;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;
import com.readwide.manager.util.FileOperationProgress;
public class ArchiveZipCreationRound7Test {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 private File file(File dir,String n,byte[] b)throws Exception{return Round4Fixtures.write(dir,n,b);}
 private boolean zip(List<File> f,File o){return ArchiveSupport.createZipArchive(f,o,null);}
 private Map<String,byte[]> read(File f)throws Exception{Map<String,byte[]>m=new TreeMap<>();try(ZipFile z=new ZipFile(f)){Enumeration<? extends ZipEntry>e=z.entries();while(e.hasMoreElements()){ZipEntry v=e.nextElement();try(InputStream in=z.getInputStream(v)){m.put(v.getName(),in.readAllBytes());}}}return m;}
 @Test public void rejectsOutputInsideSelectedDirectory()throws Exception{File dir=temp.newFolder("source");file(dir,"a",new byte[]{1});File o=new File(dir,"result.zip");assertFalse(zip(List.of(dir),o));assertFalse(o.exists());}
 @Test public void rejectsOutputInsideNestedSource()throws Exception{File dir=temp.newFolder("source"),sub=new File(dir,"nested");assertTrue(sub.mkdir());File o=new File(sub,"result.zip");assertFalse(zip(List.of(dir),o));assertFalse(o.exists());}
 @Test public void selfArchivePreservesSource()throws Exception{File f=file(temp.getRoot(),"original.zip",new byte[]{1,2,3});assertFalse(zip(List.of(f),f));assertArrayEquals(new byte[]{1,2,3},Files.readAllBytes(f.toPath()));}
 @Test public void existingOutputIsNotOverwritten()throws Exception{File src=file(temp.getRoot(),"a",new byte[]{1}),out=file(temp.getRoot(),"existing.zip",new byte[]{9});assertFalse(zip(List.of(src),out));assertArrayEquals(new byte[]{9},Files.readAllBytes(out.toPath()));}
 @Test public void duplicateRootNamesFailInsteadOfDroppingOne()throws Exception{File a=file(temp.newFolder("one"),"same.txt",new byte[]{1}),b=file(temp.newFolder("two"),"same.txt",new byte[]{2}),o=new File(temp.getRoot(),"out.zip");assertFalse(zip(List.of(a,b),o));assertFalse(o.exists());}
 @Test public void duplicateDirectoryAndFileRootFail()throws Exception{File a=temp.newFolder("same"),b=file(temp.newFolder("two"),"same",new byte[]{2}),o=new File(temp.getRoot(),"out.zip");assertFalse(zip(List.of(a,b),o));assertFalse(o.exists());}
 @Test public void noNullSourcesAreSilentlyDropped()throws Exception{File a=file(temp.getRoot(),"a",new byte[]{1}),o=new File(temp.getRoot(),"out.zip");assertFalse(zip(Arrays.asList(a,null),o));assertFalse(o.exists());}
 @Test public void preservesNestedEmptyDirectories()throws Exception{File dir=temp.newFolder("source"),sub=new File(dir,"empty/deep");assertTrue(sub.mkdirs());File o=new File(temp.getRoot(),"out.zip");assertTrue(zip(List.of(dir),o));assertTrue(read(o).containsKey("source/empty/deep/"));}
 @Test public void moreThan64FilesRoundTripExactly()throws Exception{File dir=temp.newFolder("source");for(int i=0;i<193;i++)file(dir,"한글-"+i+".bin",Round4Fixtures.data(i));File o=new File(temp.getRoot(),"out.zip");assertTrue(zip(List.of(dir),o));Map<String,byte[]> got=read(o);assertEquals(194,got.size());for(int i=0;i<193;i++)assertArrayEquals(Round4Fixtures.data(i),got.get("source/한글-"+i+".bin"));}
 @Test public void preservesUnicodeAndSpaces()throws Exception{String name="  책 😀.txt  ";File a=file(temp.getRoot(),name,new byte[]{5,6}),o=new File(temp.getRoot(),"out.zip");assertTrue(zip(List.of(a),o));assertArrayEquals(new byte[]{5,6},read(o).get(name));}
 @Test public void caseDistinctFilesBothSurvive()throws Exception{File dir=temp.newFolder("source");file(dir,"A.txt",new byte[]{1});file(dir,"a.txt",new byte[]{2});File o=new File(temp.getRoot(),"out.zip");assertTrue(zip(List.of(dir),o));Map<String,byte[]> got=read(o);assertArrayEquals(new byte[]{1},got.get("source/A.txt"));assertArrayEquals(new byte[]{2},got.get("source/a.txt"));}
 @Test public void sourceSymlinkIsRejectedWithoutReadingTarget()throws Exception{File target=file(temp.getRoot(),"private",new byte[]{9});Path link=temp.getRoot().toPath().resolve("link");Files.createSymbolicLink(link,target.toPath());File o=new File(temp.getRoot(),"out.zip");assertFalse(zip(List.of(link.toFile()),o));assertFalse(o.exists());assertArrayEquals(new byte[]{9},Files.readAllBytes(target.toPath()));}
 @Test public void nestedSymlinkIsNotFollowed()throws Exception{File dir=temp.newFolder("source"),target=file(temp.getRoot(),"private",new byte[]{9});Files.createSymbolicLink(dir.toPath().resolve("link"),target.toPath());File o=new File(temp.getRoot(),"out.zip");assertFalse(zip(List.of(dir),o));assertFalse(o.exists());}
 @Test public void danglingDestinationSymlinkIsNotFollowed()throws Exception{File a=file(temp.getRoot(),"a",new byte[]{1});Path target=temp.getRoot().toPath().resolve("absent"),link=temp.getRoot().toPath().resolve("out.zip");Files.createSymbolicLink(link,target);assertFalse(zip(List.of(a),link.toFile()));assertTrue(Files.isSymbolicLink(link));assertFalse(Files.exists(target));}
 @Test public void nullProgressStillHonorsThreadCancellation()throws Exception{File a=file(temp.getRoot(),"a",new byte[]{1}),o=new File(temp.getRoot(),"out.zip");Thread.currentThread().interrupt();try{assertFalse(zip(List.of(a),o));}finally{Thread.interrupted();}assertFalse(o.exists());}
 @Test public void cancelsWithProgressBeforeWriting()throws Exception{File a=file(temp.getRoot(),"a",new byte[]{1}),o=new File(temp.getRoot(),"out.zip");FileOperationProgress progress=new FileOperationProgress("zip",null);progress.cancel();assertFalse(ArchiveSupport.createZipArchive(List.of(a),o,progress));assertFalse(o.exists());}
 @Test public void backslashNameRejectedWithoutSilentNormalization()throws Exception{File a=file(temp.getRoot(),"a\\b",new byte[]{1}),o=new File(temp.getRoot(),"out.zip");assertFalse(zip(List.of(a),o));assertFalse(o.exists());}
 @Test public void iterativeDeepTreePreservesAllDirectories()throws Exception{File dir=temp.newFolder("source"),cursor=dir;for(int i=0;i<160;i++){cursor=new File(cursor,"d");assertTrue(cursor.mkdir());}file(cursor,"end",new byte[]{7});File o=new File(temp.getRoot(),"out.zip");assertTrue(zip(List.of(dir),o));assertEquals(162,read(o).size());}
 @Test public void closeFailureDeletesOnlyReservedOutput()throws Exception{Assume.assumeTrue("Linux /dev/full needed",new File("/dev/full").exists());File a=file(temp.getRoot(),"a",new byte[]{1}),logical=new File(temp.getRoot(),"logical.zip");final boolean[] deleted={false};File full=new File("/dev/full"){@Override public boolean exists(){return false;}@Override public Path toPath(){return logical.toPath();}@Override public String getCanonicalPath(){return logical.getAbsolutePath();}@Override public File getAbsoluteFile(){return logical;}@Override public File getParentFile(){return logical.getParentFile();}@Override public boolean createNewFile(){return true;}@Override public boolean delete(){deleted[0]=true;return true;}};assertFalse(zip(List.of(a),full));assertTrue("reserved logical output must be cleaned after stream-close failure",deleted[0]);}
}
